// Stamp the publishing commit and release version into the exported OTA bundle.
//
// Run in the OTA workflow (.github/workflows/mobile-ota.yml) right before
// `eas update`. The generated file is NOT a fingerprint source, so writing it here
// never changes the runtimeVersion — which is why only the OTA path is stamped and
// the native build path deliberately is not.
import { execSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

/** Resolve the commit being published: CI env first, then a local git fallback. */
function resolveCommit() {
  const fromEnv = process.env.GITHUB_SHA ?? process.env.EAS_BUILD_GIT_COMMIT_HASH;
  if (fromEnv && fromEnv.trim()) return fromEnv.trim();
  try {
    return execSync('git rev-parse HEAD', { encoding: 'utf8' }).trim();
  } catch {
    return 'dev';
  }
}

const commit = resolveCommit();
const releaseVersion = process.env.MOBILE_RELEASE_VERSION?.trim();
if (!releaseVersion || !/^\d+\.\d+\.\d+$/.test(releaseVersion)) {
  throw new Error('MOBILE_RELEASE_VERSION must be a semantic version such as 1.4.2');
}
const target = join(
  dirname(fileURLToPath(import.meta.url)),
  '..',
  'apps',
  'mobile',
  'lib',
  'buildInfo.generated.ts',
);

const contents = `// AUTO-GENERATED by scripts/stamp-mobile-build-info.mjs — do not edit by hand.
//
// Committed with the 'dev' placeholder; overwritten in CI before Metro exports the
// OTA bundle. NOT a fingerprint source (see lib/buildInfo.ts), so a per-commit value
// here never changes the runtimeVersion fingerprint.
export const BUILD_COMMIT = ${JSON.stringify(commit)};
export const RELEASE_VERSION = ${JSON.stringify(releaseVersion)};
`;

writeFileSync(target, contents);
console.log(
  `Stamped buildInfo.generated.ts: RELEASE_VERSION=${releaseVersion} BUILD_COMMIT=${commit.slice(0, 7)}`,
);
